; regs.asm -- chapter 7: a value in every register
; generated by gen07.py
        INCLUDE "msx.inc"
        OUTPUT "regs.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
RESULTS EQU RAM_START          ; what the program found: the debugger reads it here
init:   di
        ld sp, SYS_AREA
        xor a
        ld r, a                 ; R = 0: from here it counts
        ld a, $AA
        ex af, af'              ; A and F go to the second set
        ld bc, $1111
        ld de, $2222
        ld hl, $3333
        exx                     ; the second BC, DE and HL come in
        ld bc, $1234
        ld de, $5678
        ld hl, $9ABC
        ld ix, $C000
        ld iy, $C010
        ld a, $55
stop:   jr stop
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
